import React, { useState } from 'react';
import './PostDetails.css'; // Ensure this matches your file name
import  { useEffect }  from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';

const api = axios.create({
  baseURL: 'http://localhost:5000/api',
  timeout: 5000,
});

const PostDetail = () => {
  const { id } = useParams();
  const [postData, setPostData] = useState({
    "title": "title",
    "date": null,
    "datePosted": null,
    "description": "description",
    "photos": [],
    "participants": 0,
    "author": "",
    "authorId": null
  });
  const token = localStorage.getItem("loginToken");

  /*
  // Stuff for making postUser for testing
  const doStuff = async () => {
    try {
      const authStr = "Bearer ".concat(token);
      const response = await api.post(`/makepostuser/${id}`, {}, {headers: {Authorization: authStr}});
      console.log(response);
    } catch (err) {
      console.log("error trying to get user data");
    }
  };

  useEffect(() => {
    const fetchData = async () => {
      await doStuff();
    }
    fetchData();
  }, []);
  */

  const loadPost = async () => {
    try{
      const response = await api.get(`getpost/${id}`);
      setPostData(response.data);
    }
    catch (exp){
      console.log(exp);
    }
  }

  useEffect(() => {
    const fetchData = async () => {
      await loadPost();
    }
    fetchData();
  }, []);

  return (
    <>
    <p>{postData.title}</p>
    <p>{postData.description}</p>
    </>
  );
};

export default PostDetail;
